        return True
    v = order[i]
    for c in range(min(used + 1, k)):
        if all(colour[u] != c for u in adj[v]):
            colour[v] = c
            if colourable(i + 1, k, max(used, c + 1), order, colour, adj):
                return True
            colour[v] = -1
    return False

